//! Legacy wire decoder test for schema-1 journal events with the old 7-field
//! ActionTicket layout from commit 423d8ae8.
//!
//! This test uses actual old golden binary records generated by the old
//! production serializer at commit 423d8ae8. Each record was verified by
//! the old production decoder before being exported as a golden fixture.
//!
//! Old ActionTicket layout (7 fields):
//!   run: RunId, step: StepIdx, seq: SeqNo, action: ActionId,
//!   attempt: u16, idempotency_key: u128, capacity: u16
//!
//! Current ActionTicket layout (8 fields):
//!   run: RunId, step: StepIdx, seq: SeqNo, action: ActionId,
//!   run_attempt: u16, attempt: u16, idempotency_key: u128, capacity: u16
//!
//! This test feeds each complete old envelope to the current public parse_event
//! API and asserts the exact typed rejection for incompatible payload layout.
//!
//! not establish universal legacy compatibility for all event kinds or schemas.
use std::path::{Path, PathBuf};

use std::fs;
use vb_storage::error::JournalError;
use vb_storage::journal::parse_event;

/// Golden fixture provenance: commit 423d8ae8 old production serializer.
const OLD_SHA: &str = "423d8ae8b667d82b4d36e57d29d7ef2aede08bdf";

fn repo_root() -> Result<PathBuf, String> {
    // Try CARGO_MANIFEST_DIR first (set during compilation)
    if let Ok(manifest_dir) = std::env::var("CARGO_MANIFEST_DIR") {
        let root = PathBuf::from(manifest_dir)
            .parent()
            .unwrap_or(Path::new("."))
            .parent()
            .unwrap_or(Path::new("."))
            .to_path_buf();
        if root
            .join(".beads/vb-79ffw/old-golden/manifest.json")
            .exists()
        {
            return Ok(root);
        }
    }
    // Fall back to current directory
    let cwd = std::env::current_dir().map_err(|e| format!("current_dir: {}", e))?;
    if cwd
        .join(".beads/vb-79ffw/old-golden/manifest.json")
        .exists()
    {
        return Ok(cwd);
    }
    Err("cannot locate repo root (missing .beads/vb-79ffw/old-golden/manifest.json)".to_string())
}

fn load_golden(name: &str) -> Result<Vec<u8>, String> {
    let root = repo_root()?;
    let path = root.join(format!(".beads/vb-79ffw/old-golden/{}.bin", name));
    match fs::read(&path) {
        Ok(bytes) => {
            if bytes.is_empty() {
                Err(format!("golden fixture {} is empty", name))
            } else {
                Ok(bytes)
            }
        }
        Err(e) => Err(format!("failed to read golden fixture {}: {}", name, e)),
    }
}

fn load_manifest() -> Result<serde_json::Value, String> {
    let root = repo_root()?;
    let path = root.join(".beads/vb-79ffw/old-golden/manifest.json");
    match fs::read_to_string(&path) {
        Ok(content) => {
            serde_json::from_str(&content).map_err(|e| format!("failed to parse manifest: {}", e))
        }
        Err(e) => Err(format!("failed to read manifest: {}", e)),
    }
}

/// Verify a golden fixture's length and BLAKE3 digest against the manifest.
fn verify_fixture(name: &str, bytes: &[u8], manifest: &serde_json::Value) -> Result<(), String> {
    let cases = manifest
        .get("cases")
        .and_then(|v| v.as_array())
        .ok_or("manifest missing cases array")?;

    let case = cases
        .iter()
        .find(|c| c.get("name").and_then(|v| v.as_str()) == Some(name))
        .ok_or(format!("manifest missing case {}", name))?;

    let expected_length = case
        .get("length")
        .and_then(|v| v.as_u64())
        .ok_or(format!("manifest case {} missing length", name))?;
    let actual_length = u64::try_from(bytes.len())
        .map_err(|_| format!("fixture {} length too large for u64", name))?;
    if actual_length != expected_length {
        return Err(format!(
            "fixture {} length mismatch: expected {}, got {}",
            name, expected_length, actual_length
        ));
    }

    let expected_digest = case
        .get("blake3")
        .and_then(|v| v.as_str())
        .ok_or(format!("manifest case {} missing blake3", name))?;
    let actual_digest = blake3::hash(bytes).to_hex().to_string();
    if actual_digest != expected_digest {
        return Err(format!(
            "fixture {} BLAKE3 mismatch:\n  expected: {}\n  actual:   {}",
            name, expected_digest, actual_digest
        ));
    }

    Ok(())
}

/// Test case: small canonical values.
#[test]
fn legacy_small_canonical_rejected_by_current_decoder() -> Result<(), String> {
    let name = "small-canonical";
    let bytes = load_golden(name)?;
    let manifest = load_manifest()?;
    verify_fixture(name, &bytes, &manifest)?;

    let result = parse_event(&bytes);

    match result {
        Err(JournalError::PostcardDecodeFailed(source)) => {
            if !matches!(source, postcard::Error::DeserializeBadVarint) {
                return Err(format!(
                    "{}: wrong postcard variant: {:?} (expected DeserializeBadVarint)",
                    name, source
                ));
            }
            eprintln!(
                "[OK] {} rejected: PostcardDecodeFailed(DeserializeBadVarint)",
                name
            );
            Ok(())
        }
        Err(e) => Err(format!(
            "{}: unexpected error type: {} (expected PostcardDecodeFailed)",
            name, e
        )),
        Ok(event) => Err(format!(
            "{}: decoded successfully but should have failed: {:?}",
            name, event
        )),
    }
}

