/// Meta-test: verify all three golden fixtures load and have valid envelopes.
#[test]
fn legacy_golden_fixtures_have_valid_envelopes() -> Result<(), String> {
    let names = ["small-canonical", "high-values", "max-attempt-capacity"];
    let manifest = load_manifest()?;

    for name in names {
        let bytes = load_golden(name)?;
        verify_fixture(name, &bytes, &manifest)?;
        eprintln!("[OK] {} envelope verified ({} bytes)", name, bytes.len());
    }

    Ok(())
}

/// Meta-test: report the provenance and limitations of these fixtures.
#[test]
fn legacy_golden_provenance_and_limitations() -> Result<(), String> {
    eprintln!("Golden fixture provenance:");
    eprintln!("  Old production commit: {}", OLD_SHA);
    eprintln!("  Event kind: ActionScheduledTicket only");
    eprintln!("  Cases: 3 (small-canonical, high-values, max-attempt-capacity)");
    eprintln!("");
    eprintln!("Limitations:");
    eprintln!("  - Does not cover other JournalEvent variants");
    eprintln!("  - Does not cover pre-423d8ae8 layouts");
    eprintln!("  - Fail-closed behavior established for these specific cases");
    eprintln!("  - Universal legacy compatibility not claimed");
    Ok(())
}
